describeMatrix("serve static range", (t, { it, expect }) => {
  const BODY = "0123456789";
  const MTIME = new Date("2024-01-02T03:04:05.678Z");
  const LAST_MODIFIED = "Tue, 02 Jan 2024 03:04:05 GMT";

  function setup(
    overrides: Partial<ServeStaticOptions> & { meta?: Record<string, unknown> } = {},
    contents: (id: string) => any = () => BODY,
  ) {
    const getContents = vi.fn(contents);
    const { meta, ...rest } = overrides;
    const options: ServeStaticOptions = {
      getContents,
      getMeta: () => ({ size: 10, etag: '"v1"', mtime: MTIME, ...meta }),
      ...rest,
    };
    t.app.all("/**", (event) => serveStatic(event, options));
    return getContents;
  }

  const get = (range?: string, headers: Record<string, string> = {}, method = "GET") =>
    t.fetch("/file.txt", {
      method,
      headers: { ...(range ? { range } : {}), ...headers },
    });

  it("advertises Accept-Ranges on GET and HEAD without Range", async () => {
    setup();
    for (const method of ["GET", "HEAD"]) {
      const res = await get(undefined, {}, method);
      expect(res.status).toBe(200);
      expect(res.headers.get("accept-ranges")).toBe("bytes");
      expect(res.headers.get("content-length")).toBe("10");
      expect(res.headers.get("content-range")).toBeNull();
      if (method === "GET") expect(await res.text()).toBe(BODY);
    }
  });

  it("serves a single closed range as 206", async () => {
    setup();
    const res = await get("bytes=2-5");
    expect(res.status).toBe(206);
    expect(await res.text()).toBe("2345");
    expect(res.headers.get("content-range")).toBe("bytes 2-5/10");
    expect(res.headers.get("content-length")).toBe("4");
    expect(res.headers.get("accept-ranges")).toBe("bytes");
  });

  it("supports open, suffix and clamped ranges", async () => {
    setup();
    for (const [range, cr, len, text] of [
      ["bytes=7-", "bytes 7-9/10", "3", "789"],
      ["bytes=-3", "bytes 7-9/10", "3", "789"],
      ["bytes=8-99", "bytes 8-9/10", "2", "89"],
      ["bytes=-99", "bytes 0-9/10", "10", BODY],
      ["BYTES=2-5", "bytes 2-5/10", "4", "2345"],
    ] as const) {
      const res = await get(range);
      expect(res.status, range).toBe(206);
      expect(res.headers.get("content-range"), range).toBe(cr);
      expect(res.headers.get("content-length"), range).toBe(len);
      expect(await res.text(), range).toBe(text);
    }
  });

  it("answers HEAD with 206 headers and never reads contents", async () => {
    const getContents = setup();
    const res = await get("bytes=2-5", {}, "HEAD");
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 2-5/10");
    expect(res.headers.get("content-length")).toBe("4");
    expect(await res.text()).toBe("");
    expect(getContents).not.toHaveBeenCalled();
  });

  it("answers 416 for unsatisfiable ranges without reading contents", async () => {
    const getContents = setup();
    for (const range of ["bytes=10-", "bytes=-0", "bytes=99-100"]) {
      const res = await get(range);
      expect(res.status, range).toBe(416);
      expect(res.headers.get("content-range"), range).toBe("bytes */10");
      expect(res.headers.get("content-length"), range).toBe("0");
      expect(await res.text(), range).toBe("");
    }
    expect(getContents).not.toHaveBeenCalled();
  });

  it("ignores malformed, multi-range and unknown-unit ranges", async () => {
    setup();
    for (const range of [
      "bytes=0-1,4-5",
      "bytes=5-2",
      "items=0-1",
      "bytes=abc",
      "bytes=",
      "bytes=-",
    ]) {
      const res = await get(range);
      expect(res.status, range).toBe(200);
      expect(await res.text(), range).toBe(BODY);
      expect(res.headers.get("content-range"), range).toBeNull();
      expect(res.headers.get("content-length"), range).toBe("10");
      expect(res.headers.get("accept-ranges"), range).toBe("bytes");
    }
  });

  it("ignores Range without a known size", async () => {
    for (const size of [undefined, 0]) {
      const app = new H3().all("/**", (event) =>
        serveStatic(event, { getContents: () => BODY, getMeta: () => ({ size }) }),
      );
      const res = await app.request("/file.txt", { headers: { range: "bytes=0-3" } });
      expect(res.status).toBe(200);
      expect(await res.text()).toBe(BODY);
      expect(res.headers.get("content-range")).toBeNull();
      expect(res.headers.get("accept-ranges")).toBeNull();
    }
  });

  describe("If-Range", () => {
    for (const [name, value, status, meta] of [
      ["same strong etag", '"v1"', 206, {}],
      ["different etag", '"v2"', 200, {}],
      ["weak etag in header", 'W/"v1"', 200, {}],
      ["weak etag on asset", 'W/"v1"', 200, { etag: 'W/"v1"' }],
      ["same date", LAST_MODIFIED, 206, {}],
      ["different date", "Wed, 03 Jan 2024 03:04:05 GMT", 200, {}],
      ["invalid date", "not a date", 200, {}],
      ["no validator on asset", '"v1"', 200, { etag: undefined, mtime: undefined }],
    ] as const) {
      it(name, async () => {
        setup({ meta });
        const res = await get("bytes=2-5", { "if-range": value });
        expect(res.status).toBe(status);
        expect(await res.text()).toBe(status === 206 ? "2345" : BODY);
        if (status === 200) expect(res.headers.get("content-range")).toBeNull();
      });
    }

    it("is ignored when Range is invalid", async () => {
      setup();
      const res = await get("bytes=abc", { "if-range": '"v1"' });
      expect(res.status).toBe(200);
    });
  });

  it("keeps 304 ahead of Range", async () => {
    setup();
    const res = await get("bytes=2-5", { "if-none-match": '"v1"' });
    expect(res.status).toBe(304);
    expect(res.headers.get("content-range")).toBeNull();
    expect(await res.text()).toBe("");
  });

  it("ranges over the chosen precompressed variant", async () => {
    const files: Record<string, string> = {
      "/app.js": "x".repeat(30),
      "/app.js.gz": "abcdefghijklmnopqrst",
    };
    const options: ServeStaticOptions = {
      encodings: { gzip: ".gz" },
      getContents: (id) => files[id],
      getMeta: (id) =>
        files[id]
          ? { size: files[id].length, encoding: id.endsWith(".gz") ? "gzip" : undefined }
          : undefined,
    };
    t.app.all("/**", (event) => serveStatic(event, options));
    const res = await t.fetch("/app.js", {
      headers: { "accept-encoding": "gzip", range: "bytes=0-4" },
    });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-encoding")).toBe("gzip");
    expect(res.headers.get("content-range")).toBe("bytes 0-4/20");
    expect(res.headers.get("content-length")).toBe("5");
    expect(res.headers.get("vary")).toBe("accept-encoding");
    expect(await res.text()).toBe("abcde");
  });

  it("overrides a caller content-length on 206/416 but keeps other headers", async () => {
    setup({ headers: { "content-length": "10", "accept-ranges": "custom" } });
    const full = await get();
    const res = await get("bytes=2-5");
    expect(res.status).toBe(206);
    expect(res.headers.get("content-length")).toBe("4");
    expect(res.headers.get("accept-ranges")).toBe("custom");
    for (const h of ["etag", "last-modified", "content-type"]) {
      expect(res.headers.get(h), h).toBe(full.headers.get(h));
    }
    const res416 = await get("bytes=10-");
    expect(res416.status).toBe(416);
    expect(res416.headers.get("content-length")).toBe("0");
  });

  it("leaves 404, fallthrough and 405 untouched", async () => {
    const notFound: ServeStaticOptions = { getContents: () => BODY, getMeta: () => undefined };
    const app = new H3().all("/**", (event) => serveStatic(event, notFound));
    const r404 = await app.request("/file.txt", { headers: { range: "bytes=0-3" } });
    expect(r404.status).toBe(404);
    expect(r404.headers.get("content-range")).toBeNull();

    const ft = new H3()
      .use((event) => serveStatic(event, { ...notFound, fallthrough: true }))
      .use(() => "next");
    const rft = await ft.request("/file.txt", { headers: { range: "bytes=0-3" } });
    expect(await rft.text()).toBe("next");
