      expect(await res.text()).toBe("123");
    });

    it("ArrayBuffer", async () => {
      setup({}, () => enc.encode(BODY).buffer);
      const res = await get("bytes=1-3");
      expect(await res.text()).toBe("123");
    });

    it("Blob", async () => {
      setup({}, () => new Blob([BODY]));
      const res = await get("bytes=1-3");
      expect(await res.text()).toBe("123");
    });

    it("ReadableStream across chunks, cancelling the source", async () => {
      const cancel = vi.fn();
      setup({}, () => stream(["012", "345", "6789"], cancel));
      const res = await get("bytes=2-6");
      expect(res.status).toBe(206);
      expect(await res.text()).toBe("23456");
      await vi.waitFor(() => expect(cancel).toHaveBeenCalled());
    });

