      setup();
      const res = await get("bytes=abc", { "if-range": '"v1"' });
      expect(res.status).toBe(200);
    });
  });

  it("keeps 304 ahead of Range", async () => {
    setup();
    const res = await get("bytes=2-5", { "if-none-match": '"v1"' });
    expect(res.status).toBe(304);
    expect(res.headers.get("content-range")).toBeNull();
    expect(await res.text()).toBe("");
