  it("blocks path traversal attempts", async () => {
    const blocked = [
      "/../etc/passwd",
      "/%2e%2e/",
      "/%2E%2E/",
      "/assets/../../etc/passwd",
      "/assets/..",
      "/..\\etc\\passwd",
